/// Hierarchical category taxonomy (1–5 levels) used to organize products in
/// the catalog. Supports unique slugs and sibling-level name uniqueness.
/// Changes are audit-friendly for governance.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Optional parent category's {@link shopping_mall_categories.id}.
  parent_id String? @db.Uuid

  /// Category display name. Unique among siblings under the same parent.
  name String

  /// Globally unique slug for routing and redirects.
  slug String

  /// Business state of the category (e.g., Draft, Active, Archived).
  state String

  /// Depth in the hierarchy starting at 1 for root level.
  depth Int @db.Integer

  /// Order value for sibling sorting in navigation.
  sort_order Int @db.Integer

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  parent shopping_mall_categories? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive shopping_mall_categories[] @relation("recursive")
  shopping_mall_category_redirects shopping_mall_category_redirects[]
  shopping_mall_category_attributes shopping_mall_category_attributes[]
  shopping_mall_products shopping_mall_products[]
  shopping_mall_product_category_assignments shopping_mall_product_category_assignments[]
  shopping_mall_category_change_requests shopping_mall_category_change_requests[]

  @@unique([slug])
  @@unique([parent_id, name])
  @@index([parent_id, sort_order])
  @@index([state, depth])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

