  id String @id @db.Uuid

  /// Unique email used for login and notifications.
  email String

  /// BCrypt or equivalent password hash. Never store plaintext passwords.
  password_hash String

  /// Display name of the customer.
  name String?

  /// Contact phone number in E.164 or local format as provided.
  phone String?

  /// Business lifecycle state (e.g., unverified, active, suspended, deleted).
