/// Source business events that trigger notifications. Each record represents
/// a deduplicated, idempotent event captured from domain systems (orders,
/// shipments, payments, security). Notifications in {@link
/// shopping_mall_notifications} may be produced from a single event. Events
/// use actor_type/actor_ref_id and entity_type/entity_ref_id to reference
/// the originating actor and the business subject without polymorphic
/// nullable FKs.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_notification_events {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Canonical event type key (e.g., order_confirmed, shipment_shipped,
  /// password_reset). Used for routing and templates.
  event_type String

  /// High-level category for analytics and routing (transactional, security,
  /// operational).
  category String

  /// Actor type that produced the event (customer, seller, admin, system).
  actor_type String

  /// Identifier of the event actor within its actor_type. Stored as a UUID
  /// reference without polymorphic FK.
  actor_ref_id String @db.Uuid

  /// Business subject entity type for the event (order, shipment, payout,
  /// dispute, etc.).
  entity_type String

  /// UUID of the subject entity instance referenced by entity_type.
  entity_ref_id String @db.Uuid

  /// Idempotency key to prevent duplicate event ingestion across retries and
  /// duplicate callbacks.
  dedup_key String

  /// Optional URI to a persisted payload snapshot (e.g., JSON blob) for audit
  /// and replay.
  payload_uri String? @db.VarChar(80000)

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for audit and recovery.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_mall_notifications shopping_mall_notifications[]

  @@unique([dedup_key])
  @@index([created_at])
  @@index([event_type, created_at])
  // spellchecker: ignore-next-line
  @@index([entity_type, entity_ref_id, created_at], map: "shopping_mall_notification_events_entity_type_entity_r_3a2983a9")
  // spellchecker: ignore-next-line
  @@index([actor_type, actor_ref_id, created_at], map: "shopping_mall_notification_events_actor_type_actor_ref_f84f09b9")
  @@index([event_type(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([category(ops: raw("gin_trgm_ops"))], type: Gin)
}

