/// Catalog product master owned by a seller. Represents the parent entity
/// for variant SKUs, images, attributes, and category assignments. Each
/// product has exactly one primary category ({@link
/// shopping_mall_categories}) and may have additional category assignments
/// via {@link shopping_mall_product_category_assignments}. Title and
/// description are end-user facing. Slug is globally unique for discovery
/// and redirects. Related entities include {@link
/// shopping_mall_product_skus}, {@link shopping_mall_product_images}, {@link
/// shopping_mall_product_attribute_values}, and {@link
/// shopping_mall_product_moderation_cases}.
///
/// @namespace Catalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_products {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owning seller's {@link shopping_mall_sellers.id}.
  shopping_mall_seller_id String @db.Uuid

  /// Associated brand's {@link shopping_mall_brands.id}. Optional.
  shopping_mall_brand_id String? @db.Uuid

  /// Primary category's {@link shopping_mall_categories.id}.
  shopping_mall_category_id String @db.Uuid

  /// Applicable tax class {@link shopping_mall_tax_classes.id}.
  shopping_mall_tax_class_id String @db.Uuid

  /// Human-readable product title used in discovery and search.
  title String

  /// Globally unique, human-readable identifier for discovery and redirects.
  slug String

  /// Detailed product description; must meet minimum content policy
  /// requirements.
  description String

  /// Business visibility state (e.g., Draft, Pending Approval, Active,
  /// Archived).
  visibility_state String

  /// Item condition (e.g., New, Used, Refurbished).
  condition String

  /// Base price used when SKUs do not override price.
  base_price Float @db.DoublePrecision

  /// ISO currency code used for pricing display and calculations.
  currency String

  /// Fulfillment type (e.g., Seller-fulfilled, Platform-fulfilled).
  fulfillment_type String

  /// Whether the product uses option dimensions to generate SKUs.
  has_variants Boolean

  /// Timestamp when the product became publicly discoverable.
  published_at DateTime? @db.Timestamptz

  /// Creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp, if the product is retired.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  seller          shopping_mall_sellers     @relation(fields: [shopping_mall_seller_id], references: [id], onDelete: Cascade)
  brand           shopping_mall_brands?     @relation(fields: [shopping_mall_brand_id], references: [id], onDelete: Cascade)
  primaryCategory shopping_mall_categories  @relation(fields: [shopping_mall_category_id], references: [id], onDelete: Cascade)
  taxClass        shopping_mall_tax_classes @relation(fields: [shopping_mall_tax_class_id], references: [id], onDelete: Cascade)

  shopping_mall_restricted_products          shopping_mall_restricted_products[]
  shopping_mall_product_images               shopping_mall_product_images[]
  shopping_mall_product_category_assignments shopping_mall_product_category_assignments[]
  shopping_mall_product_options              shopping_mall_product_options[]
  shopping_mall_product_skus                 shopping_mall_product_skus[]
  shopping_mall_product_attribute_values     shopping_mall_product_attribute_values[]
  shopping_mall_product_redirects            shopping_mall_product_redirects[]
  shopping_mall_product_moderation_cases     shopping_mall_product_moderation_cases[]

  @@unique([slug])
  @@index([shopping_mall_brand_id])
  @@index([shopping_mall_tax_class_id])
  @@index([shopping_mall_seller_id, created_at])
  @@index([shopping_mall_category_id, created_at])
  @@index([visibility_state, created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

