  /// Human-readable reason/category for the merge (e.g., "auth_merge",
  /// "concurrent_device").
  reason String

  /// IP address seen at time of merge.
  ip String?

  /// URL context of the merge event.
  href String? @db.VarChar(80000)

  /// Referrer URL of the event.
