  //----
  // RELATIONS
  //----
  sourceCart shopping_mall_carts      @relation("shopping_mall_cart_merge_events_of_source_cart_id", fields: [source_cart_id], references: [id], onDelete: Cascade)
  targetCart shopping_mall_carts      @relation("shopping_mall_cart_merge_events_of_target_cart_id", fields: [target_cart_id], references: [id], onDelete: Cascade)
  customer   shopping_mall_customers? @relation(fields: [shopping_mall_customer_id], references: [id], onDelete: Cascade)

  @@index([target_cart_id, created_at])
  @@index([source_cart_id, created_at])
  // spellchecker: ignore-next-line
  @@index([shopping_mall_customer_id, created_at], map: "shopping_mall_cart_merge_events_shopping_mall_customer_ea9cce31")
}

/// Event records of cart expirations due to inactivity windows (e.g., 30
/// days for authenticated, 7 days for guests). Enables auditability of
/// expiration decisions and policy review. References {@link
